const days = [
  'domingo',
  'segunda',
  'terça',
  'quarta',
  'quinta',
  'sexta',
  'sábado'
];

// Usa o horário atual no fuso de São Paulo
const now = DateTime.now().setZone('America/Sao_Paulo');

// Converte o número do dia do Luxon para o array:
// Luxon: 1 = segunda ... 7 = domingo
// Array:  0 = domingo ... 6 = sábado
const getDayName = (date) => {
  return days[date.weekday % 7];
};

let result =
  `Hoje é ${getDayName(now)} ` +
  `${now.toFormat('dd/MM/yy')} ` +
  `às ${now.toFormat('HH:mm')}\n`;

for (let i = 1; i <= 6; i++) {
  const future = now.plus({ days: i });

  let label = '';

  if (i === 1) {
    label =
      `Amanhã é ${getDayName(future)} ` +
      `${future.toFormat('dd/MM/yy')}`;

  } else if (i === 2) {
    label =
      `Depois de amanhã é ${getDayName(future)} ` +
      `${future.toFormat('dd/MM/yy')}`;

  } else {
    label =
      `A próxima ${getDayName(future)} será dia ` +
      `${future.toFormat('dd/MM/yy')}`;
  }

  result += `${label}\n`;
}

return [
  {
    json: {
      resultado: result.trim()
    }
  }
];

