// Dados recebidos anteriormente
const dadosAnteriores = $input.item.json;

// Status do lead vindo do node "verificarAtendimentoHumano"
const statusLead = $('verificarAtendimentoHumano').item.json.status;

// Data e hora atual no fuso de São Paulo
const agora = new Date(
    new Date().toLocaleString('en-US', {
        timeZone: 'America/Sao_Paulo'
    })
);

const diaSemana = agora.getDay();
const hora = agora.getHours();

// Verifica se está em horário comercial
// Segunda a sexta, das 09:00 às 16:59
const emHorarioComercial =
    diaSemana >= 1 &&
    diaSemana <= 5 &&
    hora >= 9 &&
    hora < 22;

// A IA só é liberada em horário comercial para leads com agendamento,
// confirmação de presença ou follow-up em andamento
const statusLiberados = ['consulta_agendada', 'confirmado', 'follow_up'];
const leadLiberado = statusLiberados.includes(statusLead);

// Define se deve pausar por horário comercial
const pausarPorHorarioComercial =
    emHorarioComercial &&
    !leadLiberado;

return [
    {
        json: {
            ...dadosAnteriores,
            pausar_por_horario_comercial:
                pausarPorHorarioComercial ? 'true' : 'false'
        }
    }
];
